head.script:
// 원본 : ULDSTF30702 비밀번호 재발급 (/ui/sample/template/ULDSTF30702.xml)

/*
 * 화면 동작
 * 1. 화면 로딩시 공통코드를 조회하고 최근 1개월을 조회기간 기본값으로 설정
 * 2. 「회사명」 옆 검색 버튼 클릭시 발행기관 찾기 팝업 호출
 * 3. 「기간」 선택시 시작·종료일자를 자동으로 맞춤
 * 4. 「조회」 클릭 또는 조회영역에서 엔터 입력시 목록을 페이징 조회
 * 5. 목록 행을 더블클릭하면 상세 내용을 연다
 * 6. 「엑셀다운로드」 클릭시 그리드 내용을 내려받음
 *
 * 구성
 * 1. 조회조건 영역 - 발행기관 찾기, 조회기간, 구분 셀렉트박스
 * 2. 목록 그리드 + 페이징
 *
 * 담긴 패턴
 * - 세션에서 사용자 정보 읽기 ($c.session.getUserInfo)
 * - 공통코드 셀렉트박스 ($c.data.setCommonCode · comboCbDataSetDynamic · comboCbDataSetPeriod)
 * - 기간 선택으로 시작·종료일자 설정, 시작일>종료일 검증 ($c.date.compareFromToDate)
 * - 조회영역 엔터키로 조회 ($c.win.setEnterKeyEvent)
 * - 조회조건 필수 검증 ($c.validate.validateDataCollect)
 * - 목록 페이징 ($c.sbm.setPagingInfo)
 * - 그리드 셀 표시 가공 (displayFormatter)
 * - 첨부파일 다운로드 ($c.data.downFile)
 * - 엑셀 다운로드 ($c.data.downloadGridViewExcel)
 *
 * 이 화면이 쓰는 프로젝트 의존 모듈
 * - $c.stf · $c.cm 은 stf-front 의 공통모듈이다. 
 *
 * 복사해서 쓰는 순서
 * 1. 파일명과 meta_screenId 를 실제 화면ID 로 변경
 * 2. dmaSearch 키와 조회조건 마크업을 업무 항목으로 교체
 * 3. dltMain 컬럼과 gridView 컬럼을 업무 항목으로 교체 (gBody 의 column id 는 dataList 와 일치 필수)
 * 4. 각 통신의 action 경로를 실 API 로 교체
 * 5. 검증 fields 를 업무 규칙으로 교체
 * 6. 필요 없는 기능(팝업·기간·엑셀)은 함수와 마크업을 함께 삭제
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.gDepCd = $c.session.getUserInfo("depCd");
scwin.gEmpNo = $c.session.getUserInfo("empNo");
scwin.gLdMktTp = $c.session.getUserInfo("market");
scwin.gBondYn = $c.session.getUserInfo("bondYn");
scwin.vScrenID = "ULDSTF30702.xml";
scwin.pageIndex = 1;
scwin.pageItemCnt = 10;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author chunga
 * @date 2026. 07. 30
 * @description 페이지로드
 * @param 
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        // 초기화 함수
        await scwin.init();

        // 목록 조회
        await scwin.listReissuePassword();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30702.onpageload" });
    }
};

scwin.onpageunload = function () {
};

/**
 * @method
 * @name scwin.init
 * @author chunga
 * @date 2026. 07. 30
 * @description 초기화
 * @param 
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    // 초기 날짜 설정
    let vCurDate = $c.date.getServerDateTime();

    icaStartDate.setValue($c.date.addMonth(vCurDate, -1));
    icaEndDate.setValue(vCurDate);

    // 테스트
    icaStartDate.setValue("20200101");

    // 시장 구분 초기값 설정
    rdoMktId.setValue(scwin.gLdMktTp);

    // 시장 구분 show/hide 설정
    if (scwin.gLdMktTp !== "9") {
        grp_mkt.hide();
    }

    // 공통코드 처리
    await scwin.setCommonCode();

    // 회사명 컴포넌트
    await $c.cm.fn_com_isur(acbIsurCd, ibxComNm);

    // 조회조건의 기간 체크
    $c.date.compareFromToDate(icaStartDate, icaEndDate);

    // 조회조건 영역 엔터키 치면 자동 조회되도록 SET
    $c.win.setEnterKeyEvent(tbl_search, scwin.btn_search_onclick);

    // 통신 전 : paging 설정
    scwin.setPaginInfo();
};

/**
 * @method
 * @name scwin.setCommonCode
 * @author chunga
 * @date 2026. 07. 30
 * @description 공통코드 조회
 * @param 
 * @returns
 * @hidden N
*/
scwin.setCommonCode = async function () {
    // 기간선택 콤보박스 SET
    $c.data.comboCbDataSetPeriod(sbxPeriodTp);

    // 페이지건수 콤보박스 SET
    $c.data.comboCbDataSetDynamic(sbxPerPage, [0, 10, 25, 50, 100, 1000], 2);

	// 공통코드 설정
	const codeOptions = [
		{
			code: "CORP_USR_TP_CD",	// 법인사용자구분 콤보박스 조회
			action: "/api/discls/common/code/select-list-code-value?type=R&cdEngNm=CORP_USR_TP_CD",
			labelColumn: "text",
			valueColumn: "value",
			firstRow : ["", "전체"],
			compID: "sbxCorpUsrTpCd"  
		},
		{
			code: "APPL_RSLT_CD",	// 승인구분 콤보박스 조회
			action: "/api/discls/common/code/select-list-code-value?type=R&cdEngNm=APPL_RSLT_CD",
			labelColumn: "text",
			valueColumn: "value",
			firstRow : ["", "전체"],
			compID: "sbxApplRslt"
		}
	];

	await $c.data.setCommonCode(codeOptions);
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name scwin.btn_search_onclick
 * @author chunga
 * @date 2026. 07. 30
 * @description 조회 버튼 클릭
 * @param 
 * @returns
 * @hidden N
*/
scwin.btn_search_onclick = async function (e) {
    try {
        await scwin.listReissuePassword();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30702.btn_search_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_excel_onclick
 * @author chunga
 * @date 2026. 07. 30
 * @description 엑셀다운로드 버튼 클릭
 * @param 
 * @returns
 * @hidden N
*/
scwin.btn_excel_onclick = function (e) {
    try {
        // ASIS : "비밀번호신규 목록.xlsx"
        $c.data.downloadGridViewExcel(grdMain);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30702.btn_excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btnSearchIsurCd_onclick
 * @author chunga
 * @date 2026. 07. 30
 * @description 회사코드 검색 버튼 클릭
 * @param 
 * @returns
 * @hidden N
*/
scwin.btnSearchIsurCd_onclick = function (e) {
    try {
        //2009.09.01 채권공시관련 - 채권법인검색창    
        if (scwin.gBondYn === "Y") {
            $c.cm.IsurcdSearchBond(acbIsurCd, ibxComNm);
        } else {
            $c.cm.IsurcdSearch(acbIsurCd, ibxComNm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30702.btnSearchIsurCd_onclick" });
    }
};

/**
 * @method
 * @name scwin.sbxPeriodTp_onviewchange
 * @author chunga
 * @date 2026. 07. 30
 * @description 기간선택 콤보박스 값변경
 * @param 
 * @returns
 * @hidden N
*/
scwin.sbxPeriodTp_onviewchange = function (info) {
    try {
        $c.stf.setFromToDate(info.newValue, icaStartDate, icaEndDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30702.sbxPeriodTp_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.grdMain_oncelldblclick
 * @author chunga
 * @date 2026. 07. 30
 * @description 그리드 셀 더블클릭
 * @param 
 * @returns
 * @hidden N
*/
scwin.grdMain_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        if (columnId === "integUsrId" || columnId === "comNm" || columnId === "fileList") {
            await scwin.readNewPassword(rowIndex, columnId);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30702.grdMain_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.listReissuePassword
 * @author chunga
 * @date 2026. 07. 30
 * @description 목록 조회
 * @param 
 * @returns
 * @hidden N
*/
scwin.listReissuePassword = async function (gPageNo = 1) {

    const options = {
        validateType: "alert", // alert|mark|all
        checkType: "single", // single|multi
        focus: true,
        fields: {
            icaStartDate: { required: true, name: "시작일" },
            icaEndDate: { required: true, name: "종료일" }
        }
    };

    if (!await $c.validate.validateDataCollect(tbl_search, options)) return;

    scwin.pageIndex = gPageNo;

    // 채권공시관련 - 채권상장팀이면 시장구분을 '4'로 셋팅
    if (scwin.gBondYn === "Y") {
        dmaSearch.set("mktTpCd", "4");
    }

    dmaSearch.set("page", scwin.pageIndex);
    dmaSearch.set("size", sbxPerPage.getValue());

    const sbmOptions = {
        id: "sbmSearchPassword",
        action: "/api/discls/issueinfo/select-list-paging-reissue-password",
        method: "get",
        ref: "dmaSearch",
        target: "dltMain=body.content",
        gridview: "grdMain"
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);

    // 통신 후 : paging 설정
    scwin.setPaginInfo(result);
};

/**
 * @method
 * @name scwin.setPaginInfo
 * @author chunga
 * @date 2026. 07. 30
 * @description Paging 컴포넌트 설정
 * @param 
 * @returns
 * @hidden N
*/
scwin.setPaginInfo = function (result = {}) {
    const pagingInfo = {
        pageType: "P",                 				// S/P/A Default=P
        rowNumVisble: "grdMain|asc",				// gridView에 rowNumVisible 값 설정
        maxRowNum: 25,			  					// gridView에 최대 visibleRowNum 값 설정
        pageListId: "pglList",         				// 페이지 리스트 아이디
        pageFunction: "scwin.listReissuePassword",  // 페이징 처리 함수
        currentPage: scwin.pageIndex,               // 현재 페이지
        totalCountId: "tbxTotalCnt",     			// total count 출력 아이디
        recordPerPageId: sbxPerPage,				// 페이지 라인 수 컴포넌트 아이디
        pageSize: scwin.pageItemCnt					// 페이징 시 출력해줄 페이지 번호 개수
    };

    // 통신 전: 기본값 병합 + DataMap 컬럼 설정
    $c.sbm.setPagingInfo(pagingInfo, "dmaPaging", result.responseJSON?.body?.totalCount || 0);
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.readNewPassword
 * @author chunga
 * @date 2026. 07. 30
 * @description 그리드 신청ID 더블 클릭
 * @param 
 * @returns
 * @hidden N
*/
scwin.readNewPassword = async function (rowIndex, columnId) {
    if (columnId === "integUsrId") {
        let corpUsrRegApplSeq = dltMain.getCellData(rowIndex, "corpUsrRegApplSeq"); // SEQ

        const data = {
            integUsrId: corpUsrRegApplSeq,
            callbackFn: "scwin.btn_search_onclick"
        };

        const options = {
            id: "NEWPASS_READ",
            popupName: "비밀번호 신규조회",
            width: "580",
            height: "800",
        };

        await $c.win.openPopup("/ui/dis/issueinfo/ULDSTF30701.xml", options, data);

        // 조회 함수 호출
        await scwin.listReissuePassword();
    } else if (columnId === "comNm") {
        const param = {
            screnID: scwin.vScrenID,
            isurCd: dltMain.getCellData(rowIndex, "isurCd")
        };

        $c.stf.openPopupCorpInfo(param);
    } else if (columnId === "fileList" && !$c.util.isEmpty(dltMain.getCellData(rowIndex, "fileList"))) {
        // 첨부파일
        let url = "/api/discls/common/file/download";
        let fileData = JSON.parse(window.event.target.attributes["file-data"].value);
        const param = {
            gubun: "6",
            ...fileData
        };

        $c.data.downFile(url, fileData.attachFileNm, param);
    }
};

/**
 * @method
 * @name scwin.setFileListFormatter
 * @author chunga
 * @date 2026. 07. 30
 * @description 첨부파일 리스트 객체를 리스트 형태로 출력
 * @param 
 * @returns
 * @hidden N
*/
scwin.setFileListFormatter = function (data, formattedData, rowIndex, colIndex) {
    if (!$c.util.isEmpty(data) && $c.util.isArray(data)) {
        const ul = document.createElement("ul");

        data.forEach(fileInfo => {
            const li = document.createElement("li");
            li.textContent = fileInfo.attachFileNm;
            li.id = `${fileInfo.apfmNo}-${fileInfo.attachFileSeq}`;
            li.className = "pointer list blue mt2 mb2 ml5 mr5";
            li.setAttribute("file-data", `${JSON.stringify(fileInfo)}`);

            ul.appendChild(li);
        });

        return ul.outerHTML;
    } else {
        return "";
    }
};

/**
 * @method
 * @name scwin.applRsltExp
 * @author chunga
 * @date 2026. 07. 30
 * @description 그리드 승인구분 customFormatter
 * @param 
 * @returns
 * @hidden N
*/
scwin.applRsltExp = function (data, formattedData, rowIdx, colIdx) {
    if (data === "미처리") {
        grdMain.setCellColor(rowIdx, colIdx, "red");
    }

    return formattedData;
};
